# Borne d'arcade intégrée : bouton 🕹️, menu des jeux, jeux dans l'écran, pastilles, veille (diaporama), commandes, clavier.
from playwright.sync_api import sync_playwright
MOCK = open('/home/claude/mr/tests/mock_ble.js').read()
URL = "http://localhost:8765/code/micro-rider.html"
res = []
def check(n, c, d=""):
    res.append(bool(c)); print(("OK  " if c else "KO  ") + n + ("" if c else "   -> " + str(d)))
with sync_playwright() as p:
    b = p.chromium.launch(); pg = b.new_page(viewport={"width": 1440, "height": 900}); errs = []
    pg.on("pageerror", lambda e: errs.append(str(e))); pg.on("console", lambda m: errs.append(m.text) if m.type == "error" else None)
    pg.add_init_script(MOCK); pg.goto(URL); pg.evaluate("localStorage.clear(); localStorage.setItem('micro-rider.borne.veille','7'); localStorage.setItem('micro-rider.borne.diapo','1')"); pg.reload(); pg.wait_for_timeout(1500)
    check("départ : borne fermée, animation visible, 🕹️ présent", pg.is_hidden("#colBorne") and pg.is_visible("#promenade") and pg.is_visible("#bBorne") and pg.get_attribute("#bBorne", "aria-pressed") == "false")
    pg.click("#bBorne"); pg.wait_for_timeout(2500)
    check("🕹️ : la borne s'ouvre à gauche de l'animation, qui reste visible", pg.is_visible("#colBorne") and pg.is_visible("#promenade") and pg.evaluate("document.querySelector('#colBorne').getBoundingClientRect().right <= document.querySelector('#promenade').getBoundingClientRect().left + 2"))
    check("barre de la borne : bascule petit/grand, retour aux jeux, 6 pastilles", pg.is_visible("#bascule") and pg.is_visible("#bRetourJeux") and pg.locator(".pastille").count() == 6)
    check("l'écran de la borne montre le menu des jeux", pg.evaluate("MR.borneJeux().etat()") == "menu" and pg.is_visible(".machine .jeux canvas"))
    check("l'état est mémorisé (borne ouverte)", pg.evaluate("localStorage.getItem('micro-rider.borne.ouverte')") == "1")
    pg.keyboard.press("ArrowDown"); pg.keyboard.press("ArrowUp"); pg.keyboard.press("ArrowUp")
    check("croix : la sélection tourne dans le menu (3 entrées)", pg.evaluate("MR.borneJeux().selection()") == "veille", pg.evaluate("MR.borneJeux().selection()"))
    pg.keyboard.press("ArrowDown"); pg.keyboard.press("Enter"); pg.wait_for_timeout(400)
    check("Entrée : Chain Four se lance dans l'écran, vue petit écran", pg.evaluate("MR.borneJeux().jeuId()") == "chain4" and pg.evaluate("document.querySelector('.machine').dataset.vue") == "menu")
    pg.keyboard.press("ArrowRight"); pg.keyboard.press("Enter"); pg.wait_for_timeout(300)
    check("le clavier pilote le jeu (un pion posé) sans lancer Boost / Frein", pg.evaluate("MR.borneJeux().jeu().etat().historique.length") >= 1 and not pg.evaluate("MR.valeurs().frein") and not pg.evaluate("MR.valeurs().boost.actif"))
    pg.click("#bRetourJeux"); pg.wait_for_timeout(300)
    check("« ↩ Jeux » : retour au menu", pg.evaluate("MR.borneJeux().etat()") == "menu")
    pg.keyboard.press("ArrowDown"); pg.keyboard.press("Enter"); pg.wait_for_timeout(700)
    check("Bataille navale : écran haut, la borne passe en grand écran", pg.evaluate("MR.borneJeux().jeuId()") == "bataille" and pg.evaluate("document.querySelector('.machine').dataset.vue") == "jeu" and pg.get_attribute("#bascule", "aria-checked") == "true")
    ok = pg.evaluate("(() => { const c = document.querySelector('.machine .jeux canvas').getBoundingClientRect(), z = document.querySelector('.machine .screen').getBoundingClientRect(); return c.width <= z.width + 1 && c.height <= z.height + 1 && c.width > z.width * 0.6; })()")
    check("le jeu est ajusté à l'écran de la borne (sans débordement)", ok)
    pg.screenshot(path="/home/claude/mr/shots/e2e_borne_bataille.png")
    # pastilles : changer l'apparence
    pg.click("[data-borne=portable]"); pg.wait_for_timeout(1500)
    check("pastille console portable : l'image de borne est remplacée par le pupitre, l'écran garde le jeu", pg.evaluate("document.querySelector('.cab').hidden") and pg.evaluate("[...document.querySelectorAll('.pup')].filter((c) => !c.hidden).length") == 1 and pg.evaluate("MR.borneJeux().jeuId()") == "bataille")
    check("la pastille choisie est marquée", pg.get_attribute("[data-borne=portable]", "aria-pressed") == "true" and pg.evaluate("document.querySelector('#borne').value") == "portable")
    pg.click("#bRetourJeux"); pg.wait_for_timeout(200)
    box = pg.locator(".pup:not([hidden])").bounding_box()
    ax, ay = pg.evaluate("[PUPITRES.grand.a.x, PUPITRES.grand.a.y]")
    pg.mouse.click(box["x"] + box["width"] * ax / 1024, box["y"] + box["height"] * ay / 1536); pg.wait_for_timeout(200)
    check("clic sur le bouton A dessiné de la console : lance le jeu choisi", pg.evaluate("MR.borneJeux().etat()") == "jeu", pg.evaluate("MR.borneJeux().etat()"))
    sx, sy = pg.evaluate("[PUPITRES.grand.select.x, PUPITRES.grand.select.y]")
    pg.mouse.click(box["x"] + box["width"] * sx / 1024, box["y"] + box["height"] * sy / 1536); pg.wait_for_timeout(200)
    check("clic sur Select : retour au menu des jeux", pg.evaluate("MR.borneJeux().etat()") == "menu")
    for borne in ["steampunk", "original", "neon", "cassette", "giscard", "portable"]:
        pg.click("[data-borne=%s]" % borne); pg.wait_for_timeout(900)
    check("les 6 apparences se chargent sans erreur", not errs, errs)
    # Années 90 : commandes à sprites (orange = A)
    pg.click("[data-borne=original]"); pg.wait_for_timeout(1500)
    if pg.evaluate("document.querySelector('.machine').dataset.vue") != "menu": pg.click("#bascule"); pg.wait_for_timeout(1200)
    pg.wait_for_selector(".ctl.actif", timeout=5000); pg.wait_for_timeout(300)
    pg.evaluate("MR.borneJeux().reveil()")
    cb = pg.locator(".ctl").bounding_box()
    pg.mouse.click(cb["x"] + cb["width"] * 737 / 1024, cb["y"] + cb["height"] * 1040 / 1536); pg.wait_for_timeout(300)
    check("borne Années 90 : le bouton orange (A) lance le jeu choisi", pg.evaluate("MR.borneJeux().etat()") == "jeu", pg.evaluate("MR.borneJeux().etat()"))
    pg.click("#bRetourJeux"); pg.wait_for_timeout(200)
    # veille : diaporama des mondes après inactivité (7 s ici)
    pg.wait_for_timeout(8000)
    m0 = pg.evaluate("document.querySelector('.machine .scene').src")
    check("inactivité : la borne passe en veille, l'écran montre les mondes et les mesures", pg.evaluate("MR.borneJeux().etat()") == "veille" and pg.is_hidden(".machine .jeux") and pg.is_visible(".machine .hud"), pg.evaluate("MR.borneJeux().etat()"))
    pg.wait_for_timeout(2500)
    check("veille : le monde change régulièrement", pg.evaluate("document.querySelector('.machine .scene').src") != m0)
    pg.keyboard.press("Enter"); pg.wait_for_timeout(300)
    check("une action réveille la borne (menu) sans lancer de jeu", pg.evaluate("MR.borneJeux().etat()") == "menu" and pg.is_visible(".machine .jeux canvas"))
    # fermeture : le clavier revient à l'entraînement
    pg.click("#bBorne"); pg.wait_for_timeout(300)
    check("🕹️ de nouveau : la borne se ferme", pg.is_hidden("#colBorne") and pg.evaluate("localStorage.getItem('micro-rider.borne.ouverte')") == "0")
    pg.evaluate("MR.fixerRapport(10,'test')"); pg.keyboard.press("+"); pg.wait_for_timeout(100)
    check("borne fermée : le clavier régit le rapport comme avant", pg.evaluate("MR.rapport()") == 11, pg.evaluate("MR.rapport()"))
    pg.keyboard.press("ArrowUp"); pg.wait_for_timeout(150)
    check("borne fermée : la flèche haut déclenche le boost", pg.evaluate("MR.valeurs().boost.actif"), pg.evaluate("JSON.stringify(MR.valeurs().boost)"))
    check("pas d'erreur JS", not errs, errs); b.close()
print(f"\n{sum(res)}/{len(res)}")
